<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getSelectContext } from './select-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; speed?: number; ref?: HTMLDivElement | null; } let { children, speed = 8, ref = $bindable(null), onpointerenter, onpointerleave, ...rest }: Props = $props(); const select = getSelectContext(); let frame = 0; function start(event: PointerEvent) { onpointerenter?.(event as PointerEvent & { currentTarget: EventTarget & HTMLDivElement }); const list = document.getElementById(select.listId); const step = () => { list?.scrollBy(0, speed); frame = requestAnimationFrame(step); }; step(); } function stop(event: PointerEvent) { onpointerleave?.(event as PointerEvent & { currentTarget: EventTarget & HTMLDivElement }); cancelAnimationFrame(frame); }</script><div bind:this={ref} {...rest} aria-hidden="true" onpointerenter={start} onpointerleave={stop}>{@render children?.()}</div>
